CREATE TABLE research_public_ids (user_id TEXT PRIMARY KEY REFERENCES users(id), public_id TEXT NOT NULL UNIQUE CHECK(length(public_id)=10 AND public_id NOT GLOB '*[^0-9]*'));
INSERT OR IGNORE INTO research_public_ids(user_id,public_id) SELECT id,printf('%010d',(random() & 9223372036854775807)%10000000000) FROM users;
CREATE TRIGGER research_provision_public_id AFTER INSERT ON users BEGIN INSERT OR IGNORE INTO research_public_ids(user_id,public_id) VALUES(NEW.id,printf('%010d',(random() & 9223372036854775807)%10000000000)); END;
CREATE TABLE research_boards (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), create_operation TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(owner_id,create_operation));
CREATE TABLE board_members (board_id TEXT NOT NULL REFERENCES research_boards(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')), status TEXT NOT NULL DEFAULT 'active', version INTEGER NOT NULL DEFAULT 1, joined_at INTEGER NOT NULL, PRIMARY KEY(board_id,user_id));
CREATE INDEX board_members_user ON board_members(user_id,status);
CREATE TABLE board_invitations (id TEXT PRIMARY KEY, board_id TEXT NOT NULL REFERENCES research_boards(id), inviter_id TEXT NOT NULL REFERENCES users(id), invitee_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('editor','viewer')), version INTEGER NOT NULL, epoch INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','accepted','declined','cancelled','expired')), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX board_pending_invitation ON board_invitations(board_id,invitee_id) WHERE status='pending';
CREATE INDEX board_invitations_recipient ON board_invitations(invitee_id,status);
CREATE TABLE research_notifications (cursor INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, recipient_id TEXT NOT NULL REFERENCES users(id), board_id TEXT NOT NULL, invitation_id TEXT, event_version INTEGER NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL, read_at INTEGER);
CREATE INDEX research_notifications_recipient ON research_notifications(recipient_id,cursor);
CREATE TABLE research_notification_outbox (id TEXT PRIMARY KEY, notification_id TEXT NOT NULL REFERENCES research_notifications(id), recipient_id TEXT NOT NULL, delivered_at INTEGER, attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE research_receipts (board_id TEXT NOT NULL REFERENCES research_boards(id), user_id TEXT NOT NULL, operation_id TEXT NOT NULL, seq INTEGER NOT NULL, epoch INTEGER NOT NULL, response TEXT NOT NULL, PRIMARY KEY(board_id,user_id,operation_id));
CREATE TABLE research_tickets (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, session_hash TEXT NOT NULL, scope TEXT NOT NULL, board_id TEXT, epoch INTEGER, expires_at INTEGER NOT NULL);
CREATE TABLE research_uploads (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), operation_id TEXT NOT NULL, board_id TEXT, expires_at INTEGER NOT NULL, UNIQUE(user_id,operation_id));
CREATE TABLE research_upload_claims (upload_id TEXT NOT NULL PRIMARY KEY REFERENCES research_uploads(id), kind TEXT NOT NULL CHECK(kind IN ('activation','cleanup')), board_id TEXT REFERENCES research_boards(id), CHECK((kind='activation' AND board_id IS NOT NULL) OR (kind='cleanup' AND board_id IS NULL)));
CREATE TABLE research_assets (id TEXT NOT NULL, upload_id TEXT NOT NULL REFERENCES research_uploads(id), board_id TEXT, object_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, content_hash TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(upload_id,id));
CREATE UNIQUE INDEX research_assets_board ON research_assets(board_id,id) WHERE board_id IS NOT NULL;
CREATE TABLE research_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
